import React, { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { SubNavigationProps } from "../interfaces";

const EASE: [number, number, number, number] = [0.25, 0.46, 0.45, 0.94];
const NAV_HEIGHT = "3.75rem";

const SubNavigation: React.FC<SubNavigationProps> = ({ menuItems, submenuTitle }) => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);

  const handleScroll = (id: string) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
      setIsOpen(false);
      setIsExpanded(false);
    }
  };

  const handleClose = () => {
    setIsOpen(false);
    setIsExpanded(false);
  };

  const handleListScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    if (el.scrollTop > 0 && !isExpanded) {
      setIsExpanded(true);
    } else if (el.scrollTop === 0 && isExpanded) {
      setIsExpanded(false);
    }
  };

  const sheetHeight = isExpanded
    ? `calc(100svh - ${NAV_HEIGHT})`
    : "50svh";

  return (
    <>
      <nav className="fixed bottom-0 sm:bottom-[unset] h-[3.75rem] w-full px-0 text-Tofu z-40">
        <div className="flex justify-between items-center w-full sm:px-[3.75rem] h-full bg-black/20 backdrop-blur-xl">

          {/* Desktop Menu */}
          <div className="hidden md:flex w-full justify-center">
            <ul className="flex space-x-6">
              {menuItems.map((item, index) => (
                <li key={index} className="text-center">
                  <a
                    onClick={() => handleScroll(item)}
                    className="text-primary hover:text-secondary cursor-pointer text-nowrap"
                  >
                    {t(`submenu.${item}`)}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Mobile Toggle Button */}
          <button
            onClick={() => (isOpen ? handleClose() : setIsOpen(true))}
            className="md:hidden flex justify-between items-center px-4 w-full h-full"
            aria-expanded={isOpen}
            aria-label={isOpen ? "Close menu" : "Open menu"}
          >
            <span>{submenuTitle}</span>
            <motion.span
              animate={{ rotate: isOpen ? 180 : 0 }}
              transition={{ duration: 0.3, ease: "easeInOut" }}
              className="flex items-center"
            >
              <svg
                width="30"
                height="22"
                viewBox="0 0 30 22"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
                aria-hidden="true"
              >
                <path d="M1.16776 17.875L14.9178 4.125L28.6678 17.875" stroke="currentColor" />
              </svg>
            </motion.span>
          </button>
        </div>

        {/* Mobile Bottom Sheet */}
        <AnimatePresence>
          {isOpen && (
            <motion.div
              key="mobile-sheet"
              initial={{ y: "100%" }}
              animate={{ y: 0, height: sheetHeight }}
              exit={{ y: "100%" }}
              transition={{ duration: 0.4, ease: EASE }}
              className="md:hidden fixed bottom-0 left-0 w-full bg-black/80 backdrop-blur-xl z-50 flex flex-col"
            >
              {/* Sticky title */}
              <div className="sticky top-0 flex justify-between items-center px-4 py-4 border-b border-white/20 bg-black/60 backdrop-blur-xl shrink-0">
                <span>{submenuTitle}</span>
                <button
                  onClick={handleClose}
                  aria-label="Close menu"
                  className="flex items-center hover:opacity-60 transition-opacity"
                >
                  <motion.span
                    initial={{ rotate: 0 }}
                    animate={{ rotate: 180 }}
                    transition={{ duration: 0.3, ease: "easeInOut" }}
                    className="flex items-center"
                  >
                    <svg
                      width="30"
                      height="22"
                      viewBox="0 0 30 22"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                      aria-hidden="true"
                    >
                      <path d="M1.16776 17.875L14.9178 4.125L28.6678 17.875" stroke="currentColor" />
                    </svg>
                  </motion.span>
                </button>
              </div>

              {/* Scrollable list */}
              <div
                ref={listRef}
                onScroll={handleListScroll}
                className="overflow-y-auto flex-1"
              >
                <ul>
                  {menuItems.map((item, index) => (
                    <li
                      key={index}
                      className={`${index < menuItems.length - 1 ? "border-b border-white/20" : ""}`}
                    >
                      <a
                        onClick={() => handleScroll(item)}
                        className="block py-4 px-4 cursor-pointer"
                      >
                        {t(`submenu.${item}`)}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </nav>
    </>
  );
};

export default SubNavigation;
